const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'F(x) = F0(1 − x/h),  0 ≤ x ≤ h' },
      { kind: 'text', payload: 'F(x)' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: 'h/2' },
      { kind: 'text', payload: 'h' },
      { kind: 'text', payload: 'F0' },
      { kind: 'text', payload: 'F0/2' },
      { kind: 'text', payload: '阴影面积 W/(F0 h) = 3/8 = 0.375' }
    ];
  },
  render: function (input, metrics) {
    const W = input.viewport.widthDu;
    const H = input.viewport.heightDu;
    const left = Math.max(54, Math.min(90, W * 0.16));
    const right = Math.max(28, Math.min(56, W * 0.10));
    const top = Math.max(46, Math.min(74, H * 0.14));
    const bottom = Math.max(54, Math.min(82, H * 0.16));
    const plotW = Math.max(80, W - left - right);
    const plotH = Math.max(70, H - top - bottom);
    const ox = left;
    const oy = H - bottom;
    const xAt = function (t) { return ox + t * plotW; };
    const yAt = function (v) { return oy - v * plotH; };
    const axisRight = ox + plotW + 16;
    const axisTop = oy - plotH - 16;

    const shade = [['M', xAt(0), oy], ['L', xAt(0), yAt(1)], ['L', xAt(0.5), yAt(0.5)], ['L', xAt(0.5), oy], ['Z']];
    const curve = [['M', xAt(0), yAt(1)], ['L', xAt(1), yAt(0)]];
    const xAxis = [['M', ox, oy], ['L', axisRight, oy]];
    const yAxis = [['M', ox, oy], ['L', ox, axisTop]];
    const xHead = [['M', axisRight, oy], ['L', axisRight - 10, oy - 5], ['L', axisRight - 10, oy + 5], ['Z']];
    const yHead = [['M', ox, axisTop], ['L', ox - 5, axisTop + 10], ['L', ox + 5, axisTop + 10], ['Z']];
    const ticks = [
      ['M', xAt(0.5), oy - 4], ['L', xAt(0.5), oy + 4],
      ['M', xAt(1), oy - 4], ['L', xAt(1), oy + 4],
      ['M', ox - 4, yAt(0.5)], ['L', ox + 4, yAt(0.5)],
      ['M', ox - 4, yAt(1)], ['L', ox + 4, yAt(1)]
    ];
    const guide = [
      ['M', xAt(0.5), oy], ['L', xAt(0.5), yAt(0.5)],
      ['M', ox, yAt(0.5)], ['L', xAt(0.5), yAt(0.5)]
    ];

    return {
      schemaVersion: 1,
      sceneId: 'f-x-linear-shade',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'shade', commands: shade },
        { id: 'curve', commands: curve },
        { id: 'xAxis', commands: xAxis },
        { id: 'yAxis', commands: yAxis },
        { id: 'xHead', commands: xHead },
        { id: 'yHead', commands: yHead },
        { id: 'ticks', commands: ticks },
        { id: 'guide', commands: guide }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'shade', fill: '#7FB3D5AA', stroke: { width: 1 } },
          { type: 'path', pathId: 'guide', fill: '#26354A', stroke: { width: 1, dash: [4, 4] } },
          { type: 'path', pathId: 'curve', fill: '#1F4E79', stroke: { width: 2.5, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'xAxis', fill: '#26354A', stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'yAxis', fill: '#26354A', stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'xHead', fill: '#26354A' },
          { type: 'path', pathId: 'yHead', fill: '#26354A' },
          { type: 'path', pathId: 'ticks', fill: '#26354A', stroke: { width: 1.5, cap: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: left + plotW / 2, y: top * 0.45 }, hAlign: 'center', vAlign: 'middle', color: '#1F4E79' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: left - 12, y: yAt(1) - 18 }, hAlign: 'right', vAlign: 'bottom', color: '#26354A' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: axisRight + 4, y: oy }, hAlign: 'left', vAlign: 'middle', color: '#26354A' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: ox - 6, y: oy + 6 }, hAlign: 'right', vAlign: 'top', color: '#26354A' },
          { type: 'label', contentId: metrics[4].contentId, anchor: { x: xAt(0.5), y: oy + 8 }, hAlign: 'center', vAlign: 'top', color: '#26354A' },
          { type: 'label', contentId: metrics[5].contentId, anchor: { x: xAt(1), y: oy + 8 }, hAlign: 'center', vAlign: 'top', color: '#26354A' },
          { type: 'label', contentId: metrics[6].contentId, anchor: { x: ox - 8, y: yAt(1) }, hAlign: 'right', vAlign: 'middle', color: '#26354A' },
          { type: 'label', contentId: metrics[7].contentId, anchor: { x: ox - 8, y: yAt(0.5) }, hAlign: 'right', vAlign: 'middle', color: '#26354A' },
          { type: 'label', contentId: metrics[8].contentId, anchor: { x: left, y: oy + 34 }, hAlign: 'left', vAlign: 'top', color: '#1F4E79' }
        ]
      }
    };
  }
};
